def max_Product(arr):
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements")

    # Initialize variables to track the two largest and two smallest numbers
    max1 = max2 = float('-inf')  # Largest and second-largest numbers
    min1 = min2 = float('inf')   # Smallest and second-smallest numbers

    # Iterate through the array to find the two largest and two smallest numbers
    for num in arr:
        # Update the largest and second-largest numbers
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update the smallest and second-smallest numbers
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Calculate the products of the two largest and two smallest numbers
    product1 = max1 * max2
    product2 = min1 * min2

    # Return the pair with the highest product in ascending order
    if product1 >= product2:
        return (min(max1, max2), max(max1, max2))
    else:
        return (min(min1, min2), max(min1, min2))

# Example test cases
assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)
assert max_Product([0, -1, -2, -4, 5, 0, -6]) == (-6, -4)
assert max_Product([1, 10, -5, 1, -100]) == (-100, -5)
assert max_Product([-1, -2, -3, -4]) == (-3, -4)
```

