def extract_even(data):
    def is_even(x):
        return isinstance(x, int) and x % 2 == 0

    def process(element):
        if isinstance(element, tuple):
            # Recursively process nested tuples
            return tuple(process(sub) for sub in element if isinstance(sub, tuple) or is_even(sub))
        return element if is_even(element) else None

    # Process the top-level tuple and filter out None values
    return tuple(filter(lambda x: x is not None, (process(item) for item in data)))

# Example Usage
assert extract_even((4, 5, (7, 6, (2, 4)), 6, 8)) == (4, (6, (2, 4)), 6, 8)
```

