def diff_even_odd(nums):
    first_even = None
    first_odd = None

    for num in nums:
        if first_even is None and num % 2 == 0:
            first_even = num
        if first_odd is None and num % 2 != 0:
            first_odd = num

        # Break loop if both even and odd numbers are found
        if first_even is not None and first_odd is not None:
            break

    # Calculate the difference
    if first_even is not None and first_odd is not None:
        return abs(first_even - first_odd)
    else:
        raise ValueError("List must contain at least one even and one odd number.")

# Example usage and test
assert diff_even_odd([1, 3, 5, 7, 4, 1, 6, 8]) == 3
```

